def solve(inputs: dict) -> float:
    M = inputs.get('M') or inputs.get('matrix')
    n = int(inputs.get('power', inputs.get('n', 1)))
    mod = int(inputs.get('mod', 10**9+7))
    A = [list(map(int, row)) for row in M]
    def matmul(X, Y):
        return [[(X[0][0]*Y[0][0] + X[0][1]*Y[1][0]) % mod,
                 (X[0][0]*Y[0][1] + X[0][1]*Y[1][1]) % mod],
                [(X[1][0]*Y[0][0] + X[1][1]*Y[1][0]) % mod,
                 (X[1][0]*Y[0][1] + X[1][1]*Y[1][1]) % mod]]
    R = [[1, 0], [0, 1]]
    while n > 0:
        if n & 1:
            R = matmul(R, A)
        A = matmul(A, A)
        n >>= 1
    return float((R[0][0] + R[0][1] + R[1][0] + R[1][1]) % mod)

